256	    /**
257	     * Replays the owner originally created for an already-seen idempotency key, so a repeated
258	     * create returns that owner with 200 instead of storing a duplicate. Returns {@code null}
259	     * when there is no key or the key has not been seen, in which case the create proceeds
260	     * normally.
261	     */
262	    private ResponseEntity<OwnerDto> replayIfDuplicateKey(String idempotencyKey) {
263	        if (idempotencyKey == null) {
264	            return null;
265	        }
266	        return idempotencyStore.find(idempotencyKey)
267	            .map(clinicService::findOwnerById)
268	            .map(ownerMapper::toOwnerDto)
269	            .map(ownerDto -> new ResponseEntity<>(ownerDto, HttpStatus.OK))
270	            .orElse(null);
