20	
21	import java.time.LocalDate;
22	import java.util.Collection;
23	
24	/**
25	 * Computes an owner's membership standing from its stored fields. An owner earns
26	 * {@link #membershipPoints(Owner) membership points} — starting at 0 and gaining
27	 * {@link #EMAIL_POINTS} for a present email, {@link #SOLE_NAMESAKE_POINTS} for having no
28	 * namesakes (a {@code namesakeCount} of 0), {@link #LARGE_HOUSEHOLD_POINTS} for a household of
29	 * {@link #LARGE_HOUSEHOLD_SIZE} or more, and {@link #TENURE_POINTS} once tenure exceeds
30	 * {@link #TENURE_THRESHOLD_FISCAL_YEARS} fiscal years. Those points map to a numeric
31	 * {@link #membershipLevel(Owner) membership level} from {@link #MIN_LEVEL} to {@link #MAX_LEVEL}.
32	 */
33	public abstract class MembershipLevelCalculator {
34	
35	    /** Points awarded when the owner has an email address. */
36	    public static final int EMAIL_POINTS = 2;
37	
38	    /** Points awarded when the owner has no namesakes (a {@code namesakeCount} of 0). */
39	    public static final int SOLE_NAMESAKE_POINTS = 1;
40	
41	    /** Household size, in members, at or above which the large-household points are awarded. */
42	    public static final int LARGE_HOUSEHOLD_SIZE = 3;
43	
44	    /** Points awarded when the owner belongs to a household of {@link #LARGE_HOUSEHOLD_SIZE} or more. */
45	    public static final int LARGE_HOUSEHOLD_POINTS = 2;
46	
47	    /** Elapsed fiscal years an owner's tenure must exceed to earn the tenure points. */
48	    public static final long TENURE_THRESHOLD_FISCAL_YEARS = 1;
49	
50	    /** Points awarded when the owner's tenure exceeds {@link #TENURE_THRESHOLD_FISCAL_YEARS} fiscal years. */
51	    public static final int TENURE_POINTS = 3;
52	
53	    /** Lowest level this calculator awards, given to owners scoring 0-1 points. */
54	    public static final int MIN_LEVEL = 1;
55	
56	    /** Highest level this calculator awards, reached once an owner scores 6 or more points. */
57	    public static final int MAX_LEVEL = 4;
58	
59	    /**
60	     * Return the membership points for the given owner: 0 plus {@link #EMAIL_POINTS} when an
61	     * email is present, {@link #SOLE_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
62	     * {@link #LARGE_HOUSEHOLD_POINTS} for a household of {@link #LARGE_HOUSEHOLD_SIZE} or more,
63	     * and {@link #TENURE_POINTS} when tenure exceeds {@link #TENURE_THRESHOLD_FISCAL_YEARS} fiscal years.
64	     */
65	    public static int membershipPoints(Owner owner) {
66	        int points = 0;
67	        if (owner.hasEmail()) {
68	            points += EMAIL_POINTS;
69	        }
70	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
71	            points += SOLE_NAMESAKE_POINTS;
72	        }
73	        if (hasLargeHousehold(owner)) {
74	            points += LARGE_HOUSEHOLD_POINTS;
75	        }
76	        if (hasQualifyingTenure(owner)) {
77	            points += TENURE_POINTS;
78	        }
79	        return points;
80	    }
81	
82	    /**
83	     * Return the membership level for the given owner, mapped from its
84	     * {@link #membershipPoints(Owner) membership points}: level 1 for 0-1 points, 2 for 2-3,
85	     * 3 for 4-5, and {@link #MAX_LEVEL} for 6 or more.
86	     */
87	    public static int membershipLevel(Owner owner) {
88	        int points = membershipPoints(owner);
89	        return Math.min(MAX_LEVEL, MIN_LEVEL + points / 2);
90	    }
91	
92	    /**
93	     * Return the owner's effective membership level: its {@link #membershipLevel(Owner) level}
94	     * lowered to the owner's stored {@code membershipLevelCap} when that cap is present and smaller.
95	     * An owner with no recorded cap keeps its uncapped level.
96	     */
97	    public static int effectiveMembershipLevel(Owner owner) {
98	        int level = membershipLevel(owner);
99	        Integer cap = owner.getMembershipLevelCap();
100	        return cap == null ? level : Math.min(level, cap);
101	    }
102	
103	    /**
104	     * Return the membership-level ceiling for a new owner joining the given household members,
105	     * namely one above the highest {@link #effectiveMembershipLevel(Owner) effective level} among
106	     * them. Only meaningful for a non-empty household; an owner starting a new household has no cap.
107	     */
108	    public static int householdLevelCeiling(Collection<Owner> householdMembers) {
109	        int maxLevel = householdMembers.stream()
110	            .mapToInt(MembershipLevelCalculator::effectiveMembershipLevel)
111	            .max()
112	            .orElse(MAX_LEVEL);
113	        return maxLevel + 1;
114	    }
115	
116	    /**
117	     * Whether the owner belongs to a household of {@link #LARGE_HOUSEHOLD_SIZE} or more members.
118	     * An owner with no recorded household size is treated as not qualifying.
119	     */
120	    private static boolean hasLargeHousehold(Owner owner) {
121	        Integer householdSize = owner.getHouseholdSize();
122	        return householdSize != null && householdSize >= LARGE_HOUSEHOLD_SIZE;
123	    }
124	
125	    /**
126	     * Whether the owner's tenure, measured as the fiscal years elapsed from its registration
127	     * date to today, exceeds {@link #TENURE_THRESHOLD_FISCAL_YEARS}. An owner with no
128	     * registration date has no tenure.
129	     */
130	    private static boolean hasQualifyingTenure(Owner owner) {
131	        LocalDate registrationDate = owner.getRegistrationDate();
132	        if (registrationDate == null) {
133	            return false;
134	        }
135	        return FiscalYearResolver.elapsedYears(registrationDate, LocalDate.now())
136	            > TENURE_THRESHOLD_FISCAL_YEARS;
137	    }
138	
139	}
