370	        if (currentOwner == null) {
371	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
372	        }
373	        currentOwner.setAddress(ownerFieldsDto.getAddress());
374	        currentOwner.setCity(ownerFieldsDto.getCity());
375	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
376	        currentOwner.setLastName(ownerFieldsDto.getLastName());
377	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
378	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
379	        this.clinicService.saveOwner(currentOwner);
380	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
381	    }
